import{_ as i,o as e,c as o,a2 as s}from"./chunks/framework.YT-FC_Xx.js";const d=JSON.parse('{"title":"GitHub 登录（可选）","description":"","frontmatter":{},"headers":[],"relativePath":"guide/github-login.md","filePath":"guide/github-login.md","lastUpdated":1793160153000}'),a={name:"guide/github-login.md"};function l(n,t,r,g,c,u){return e(),o("div",null,[...t[0]||(t[0]=[s('<h1 id="github-登录-可选" tabindex="-1">GitHub 登录（可选） <a class="header-anchor" href="#github-登录-可选" aria-label="Permalink to &quot;GitHub 登录（可选）&quot;">​</a></h1><p>开启后，用户可以在个人资料页绑定自己的 GitHub 账号，之后在登录页点 <strong>使用 GitHub 登录</strong> 一键登录。面板用户仍由管理员创建：<strong>没有绑定过的 GitHub 账号无法登录</strong>，也不会自动注册新用户。密码登录照常可用，也可以<a href="#禁止管理员使用密码登录">禁止管理员使用密码登录</a>。</p><h2 id="管理员-开启" tabindex="-1">管理员：开启 <a class="header-anchor" href="#管理员-开启" aria-label="Permalink to &quot;管理员：开启&quot;">​</a></h2><ol><li>打开 GitHub → <strong>Settings</strong> → <strong>Developer settings</strong> → <strong>OAuth Apps</strong> → <strong>New OAuth App</strong>： <ul><li><strong>Homepage URL</strong>：面板网址，例如 <code>https://panel.example.com</code></li><li><strong>Authorization callback URL</strong>：面板网址加 <code>/github-callback</code>，例如 <code>https://panel.example.com/github-callback</code>。只填这一个，登录和绑定都回到这里。填浏览器地址栏里访问面板的地址（前端地址），不是后端 API 地址；面板 <strong>设置 → 安全与登录</strong> 的说明里会直接显示应该填的地址</li></ul></li><li>创建后记下 <strong>Client ID</strong>，再点 <strong>Generate a new client secret</strong> 生成 <strong>Client Secret</strong></li><li>面板 <strong>设置</strong> → <strong>安全与登录</strong>：打开 <strong>启用 GitHub 登录</strong>，填入 Client ID 和 Client Secret，保存</li></ol><p>Client Secret 只有管理员能看到，也不会写进 JSON 备份。</p><h2 id="用户-绑定和登录" tabindex="-1">用户：绑定和登录 <a class="header-anchor" href="#用户-绑定和登录" aria-label="Permalink to &quot;用户：绑定和登录&quot;">​</a></h2><ol><li>先用密码登录，进入 <strong>更多</strong> 页（手机端底部 <strong>更多</strong>，电脑上点左下角 <strong>账户与登录</strong>）</li><li>在 <strong>账户</strong> 里点 <strong>GitHub 登录</strong>，输入当前密码，点 <strong>去 GitHub 授权</strong>，授权后自动回到面板，这一行会显示“已绑定 + GitHub 用户名”</li><li>以后在登录页点 <strong>使用 GitHub 登录</strong>，GitHub 授权后直接进入面板</li></ol><ul><li>一个面板用户只能绑定一个 GitHub 账号，一个 GitHub 账号也只能绑定一个面板用户</li><li>解绑同样在个人资料页，需要输入当前密码</li><li>账号被停用后，GitHub 登录也会被拒绝；删除用户时会一并删除绑定</li><li>面板只读取 GitHub 账号的 ID 和用户名，不申请任何仓库或邮箱权限</li></ul><h2 id="禁止管理员使用密码登录" tabindex="-1">禁止管理员使用密码登录 <a class="header-anchor" href="#禁止管理员使用密码登录" aria-label="Permalink to &quot;禁止管理员使用密码登录&quot;">​</a></h2><p>开启 GitHub 登录后，<strong>设置</strong> → <strong>安全与登录</strong> 里可以打开 <strong>禁止管理员使用密码登录</strong>：管理员账号只能用 GitHub 或通行证密钥登录，即使密码泄露也登录不了管理后台。<strong>普通用户不受影响</strong>，照常用密码登录，配置规则、复制订阅都不变；登录页也照常显示用户名和密码。</p><ul><li>打开前所有启用中的管理员都要先在个人资料页绑定 GitHub，否则保存会被拒绝并列出未绑定的管理员</li><li>管理员在登录页输入正确的账号密码时，会提示改用 GitHub 或通行证密钥登录</li><li>关闭 GitHub 登录，或者 Client ID / Secret 被清空时，管理员的密码登录会自动恢复</li><li>开关打开期间，管理员不能解绑自己的 GitHub</li><li>手机 App 里不能用 GitHub 登录，管理员在 App 里只能用通行证密钥登录</li></ul><p>GitHub 访问不了、OAuth App 配错等原因导致管理员登录不了时，在面板服务器上执行下面的命令，重新允许管理员使用密码登录（无需重启面板）：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> compose</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> exec</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> backend</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /app/paneld</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> enable-password-login</span></span></code></pre></div><p>不是用 Docker 部署时，在后端所在机器上，用和面板相同的环境变量（<code>DB_TYPE</code>、<code>DB_PATH</code> 或 <code>DATABASE_URL</code>）运行 <code>paneld enable-password-login</code>。</p><h2 id="注意" tabindex="-1">注意 <a class="header-anchor" href="#注意" aria-label="Permalink to &quot;注意&quot;">​</a></h2><ul><li>手机 App（WebView）里不显示 GitHub 登录入口，请在浏览器里使用</li><li>GitHub 提示 “redirect_uri 与此应用程序无关” 时，是 OAuth App 的 callback URL 和面板发出的地址对不上：协议、域名、端口要完全一致，路径是 <code>/github-callback</code>。面板换了域名时也要同步修改</li><li>后端需要能访问 <code>github.com</code> 和 <code>api.github.com</code>；面板在访问不了 GitHub 的网络里时无法使用此功能</li><li>授权过程中的临时状态保存在后端内存里，有效期 10 分钟，后端重启后需要重新点一次</li><li>面板的 JSON 导出不包含 GitHub 绑定，用 JSON 导入迁移后，用户需要重新绑定</li></ul>',16)])])}const h=i(a,[["render",l]]);export{d as __pageData,h as default};
